// Storage keys are generated by the server, not supplied as arbitrary paths.
// The attachment UUID is independent of the database ticket UUID.
export function supportAttachmentFilename(storageKey: string) {
  const uuid = "[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}";
  if (!new RegExp(`^${uuid}/${uuid}$`, "i").test(storageKey))
    throw Error("Invalid support attachment path");
  return storageKey.split("/")[1];
}
